{
  "name": "nodecode-magpie",
  "version": "0.6.4",
  "description": "paid key with full tools, and a free key whose eval image also serves requests that declare no tools; deepseek model aliases map to nodecode-cyber-v1; finished background evals are logged for later images and vision results are cached; eval ids stay addressable across images; tool_choice no longer disables the free image; idle images are evicted",
  "magpie": {
    "icon": "data:image/png;base64,"
  },
  "type": "module",
  "main": "./index.mjs",
  "exports": {
    ".": "./index.mjs",
    "./server": "./index.mjs"
  },
  "files": [
    "index.mjs",
    "lib",
    "assets",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "magpie",
    "opencode",
    "opencode-plugin",
    "nodecode",
    "provider"
  ],
  "license": "MIT",
  "author": "Chao Liu",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ChasLui/nodecode-magpie.git"
  },
  "homepage": "https://github.com/ChasLui/nodecode-magpie",
  "bugs": {
    "url": "https://github.com/ChasLui/nodecode-magpie/issues"
  },
  "engines": {
    "node": ">=18.17"
  },
  "scripts": {
    "test": "node --test",
    "test:watch": "node --test --watch"
  }
}
